const idea = $input.first().json.body.idea || $input.first().json.idea || $input.first().json.body.title;
const category = $input.first().json.body.category_id || 24;
return { idea, category, round: 0, bestTitle: '', bestScore: 0, history: [] };

const text = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
let titles = [];
try { titles = JSON.parse(text); } catch(e) {
  const match = text.match(/\[.*?\]/s);
  if (match) try { titles = JSON.parse(match[0]); } catch(e2) {}
}
if (!Array.isArray(titles) || titles.length === 0) {
  titles = [text.split('\n').find(l => l.trim()) || 'Untitled'];
}
return titles.map(t => ({ title: t.trim(), score: 0, round: 1 }));

const items = $input.all();
const scored = items.map(item => {
  const p = item.json.probabilities;
  const score = Math.round((p.low||0)*0 + (p.med||0)*50 + (p.high||0)*100);
  const title = $items('One by one').find(i => true)?.json?.title || item.json.title;
  return { title, score, probabilities: p, decision: item.json.decision, helps: item.json.helps, hurts: item.json.hurts };
});
scored.sort((a,b) => b.score - a.score);
const top2 = scored.slice(0, 2);
const best = top2[0];

return {
  top2,
  best: { title: best.title, score: best.score },
  allScored: scored.map(s => s.title + ' → ' + s.score),
  round: 1,
  idea: $('Init state').first().json.idea,
  category: $('Init state').first().json.category
};

