});
const prevBest = $('Rank & pick top 2').first().json.best;
const allRounds = [...($('Rank & pick top 2').first().json.allScored || []), ...scored.map(s => s.title + ' → ' + s.score)];
const globalBest = [...scored, prevBest].sort((a,b) => b.score - a.score)[0];

return {
  best: globalBest,
  round1Best: prevBest,
  round2Scored: scored,
  allRounds,
  idea: $('Init state').first().json.idea
};
